export function mergeRouters<TRouters extends AnyRouter[]>(
  ...routerList: [...TRouters]
): MergeRouters<TRouters> {
  const mergedProcedures: ProcedureRecord = omitPrototype({});
  const mergedConfig: AnyRootConfig = routerList[0]._def._config;

  for (const router of routerList) {
    if (router._def._config !== mergedConfig) {
      throw new Error("All routers must have the same configuration");
    }

    for (const [path, procedure] of Object.entries(router._def.procedures)) {
      if (mergedProcedures[path]) {
        throw new Error(`Duplicate key: ${path}`);
      }
      mergedProcedures[path] = procedure;
    }
  }

  const _def: AnyRouterDef<typeof mergedConfig> = {
    _config: mergedConfig,
    router: true,
    procedures: mergedProcedures,
    ...emptyRouter,
    record: mergedProcedures,
    queries: Object.entries(mergedProcedures)
      .filter((pair) => (pair[1] as any)._def.query)
      .reduce((acc, [key, val]) => ({ ...acc, [key]: val }), {}),
    mutations: Object.entries(mergedProcedures)
      .filter((pair) => (pair[1] as any)._def.mutation)
      .reduce((acc, [key, val]) => ({ ...acc, [key]: val }), {}),
    subscriptions: Object.entries(mergedProcedures)
      .filter((pair) => (pair[1] as any)._def.subscription)
      .reduce((acc, [key, val]) => ({ ...acc, [key]: val }), {}),
  };

  const router: AnyRouter = {
    ...mergedProcedures,
    _def,
    createCaller(ctx: typeof mergedConfig['$types']['ctx']) {
      return createCallerFactory<typeof mergedConfig>()(router as any)(ctx);
    },
    getErrorShape(opts) {
      const { path, error } = opts;
      const { code } = opts.error;
      const shape: DefaultErrorShape = {
        message: error.message,
        code: TRPC_ERROR_CODES_BY_KEY[code],
        data: {
          code,
          httpStatus: getHTTPStatusCodeFromError(error),
        },
      };
      if (mergedConfig.isDev && typeof opts.error.stack === 'string') {
        shape.data.stack = opts.error.stack;
      }
      if (typeof path === 'string') {
        shape.data.path = path;
      }
      return this._def._config.errorFormatter({ ...opts, shape });
    },
  };

  return router as any;
}
